questions.safe_code:
1  String fileName = request.getParameter("P");
2  response.setHeader("Content-Disposition", "attachment;filename=" + fileName + ";");
3  // 경로순회 문자열(.. / \)을 제거하고 사용한다.
4  fileName = fileName.replaceAll("\\.", "").replaceAll("/", "").replaceAll("\\\\", "");
5  FileInputStream fis = new FileInputStream("C:/datas/" + fileName);
6  BufferedInputStream bis = new BufferedInputStream(fis);
7  BufferedOutputStream bos = new BufferedOutputStream(response.getOutputStream());

